  var localeCache = null;
  var localeLang = "";
  async function applyLocale() {
    const lang = settings.lang || "ru";
    if (lang === localeLang && localeCache) return;
    try {
      const r = await fetch(`/locale/${lang}.json`);
      localeCache = await r.json();
      localeLang = lang;
    } catch {
      localeCache = null;
      return;
    }
    document.querySelectorAll("[data-i18n]").forEach((n) => {
      const key = n.dataset.i18n ?? "";
      const v = localeCache?.[key];
      if (!v) return;
      if (n.children.length === 0) {
        n.textContent = v;
      } else {
        n.childNodes.forEach((cd) => {
          if (cd.nodeType === 3) cd.textContent = "";
        });
        n.insertBefore(document.createTextNode(v), n.firstChild);
      }
    });
  }
