      return { ok: false, reason: `\u041D\u0443\u0436\u043D\u0430 \u0446\u0435\u043B\u044C: ${valid.slice(0, 3).map((v) => v.label).join(", ")}${valid.length > 3 ? "\u2026" : ""}` };
