  async function requestMatchStart() {
    try {
      if (typeof window.fetch !== "function") return null;
      const ctl = new AbortController();
      const timer = window.setTimeout(() => ctl.abort(), 700);
      const r = await window.fetch(`http://${window.location.hostname}:8080/api/match/start`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        signal: ctl.signal,
        body: JSON.stringify({
          playerFaction: picked,
          enemyFaction: battle.enemyFaction,
          difficulty: battle.difficulty,
          deckId: battle.playerDeckId,
          practice: battle.practice,
          mmr: meta.mmr
        })
      });
      window.clearTimeout(timer);
      if (!r.ok) return null;
      const j = await r.json();
      return j.match_id ?? null;
    } catch {
      return null;
    }
  }
  function applyBattleBg() {
    const fac = String(battle.playerFaction ?? picked).toLowerCase();
    const imgEl = document.getElementById("battleBgImg");
    const vidEl = document.getElementById("battleBgVideo");
    const backdrop = document.getElementById("backdrop");
    if (!backdrop) return;
    const imgUrls = [`/bg/battle/battle_${fac}`, `/bg/battle/battle`, `img/board_arena.png`];
    const vidUrls = [`/bg/animated/battle/battle_${fac}`, `/bg/animated/battle/battle`];
    const loadImg = (idx) => {
      if (idx >= imgUrls.length) {
        if (imgEl) imgEl.classList.remove("show");
        backdrop.classList.remove("hasCustomBg");
        loadVid(0);
        return;
      }
      const url = imgUrls[idx];
      const probe = new Image();
      probe.onload = () => {
        if (imgEl) {
          imgEl.src = url;
          imgEl.classList.add("show");
          imgEl.style.opacity = "0.92";
        }
        backdrop.classList.add("hasCustomBg");
        if (vidEl) {
          vidEl.classList.remove("show");
          vidEl.style.display = "none";
          vidEl.pause();
        }
      };
      probe.onerror = () => loadImg(idx + 1);
      probe.src = url;
    };
    const loadVid = (idx) => {
      if (!vidEl || idx >= vidUrls.length) return;
      const url = vidUrls[idx];
      const test = document.createElement("video");
      test.muted = true;
      test.oncanplay = () => {
        vidEl.src = url;
        vidEl.style.display = "block";
        vidEl.classList.add("show");
        vidEl.style.opacity = "0.92";
        vidEl.play().catch(() => {
        });
        backdrop.classList.add("hasCustomBg");
        if (imgEl) imgEl.classList.remove("show");
      };
      test.onerror = () => loadVid(idx + 1);
      test.src = url;
      window.setTimeout(() => {
        if (test.readyState < 2) loadVid(idx + 1);
      }, 800);
    };
    loadImg(0);
  }
